import{_ as e,c as r,o as i,af as t}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"5、【需】 乾下坎上","description":"溫公易說 - 5、【需】 乾下坎上","frontmatter":{"title":"5、【需】 乾下坎上","description":"溫公易說 - 5、【需】 乾下坎上"},"headers":[],"relativePath":"classics/wengong/006.md","filePath":"classics/wengong/006.md"}'),n={name:"classics/wengong/006.md"};function l(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="_5、【需】-乾下坎上" tabindex="-1">5、【需】 乾下坎上 <a class="header-anchor" href="#_5、【需】-乾下坎上" aria-label="Permalink to “5、【需】 乾下坎上”">​</a></h1><h3 id="彖曰-需須也-險在前也。剛健而不陷-其義不困窮矣。需有孚光亨貞吉-位乎天位以正中也。利涉大川-往有功也。" tabindex="-1">彖曰：需須也，險在前也。剛健而不陷，其義不困窮矣。需有孚光亨貞吉，位乎天位以正中也。利涉大川，往有功也。 <a class="header-anchor" href="#彖曰-需須也-險在前也。剛健而不陷-其義不困窮矣。需有孚光亨貞吉-位乎天位以正中也。利涉大川-往有功也。" aria-label="Permalink to “彖曰：需須也，險在前也。剛健而不陷，其義不困窮矣。需有孚光亨貞吉，位乎天位以正中也。利涉大川，往有功也。”">​</a></h3><p>坎陷也，其雲不陷何需然後進，故不陷也。又曰位乎天位以正中者，何有孚光亨貞吉者，人君所以待天下之道也。</p><h3 id="象曰-雲上於天-需。君子以飲食宴樂。" tabindex="-1">象曰：雲上於天，需。君子以飲食宴樂。 <a class="header-anchor" href="#象曰-雲上於天-需。君子以飲食宴樂。" aria-label="Permalink to “象曰：雲上於天，需。君子以飲食宴樂。”">​</a></h3><p>需之為飲食何也？雲上於天，萬物之滂沱下施，萬物飲之以豐以肥以榮以滋，飲食燕樂及下之道也。</p><h3 id="初九-需於郊-利用恆-無咎。-象曰-需於郊-不犯難行也。利用恆-無咎-未失常也。" tabindex="-1">初九：需於郊，利用恆，無咎。 象曰：需於郊，不犯難行也。利用恆，無咎，未失常也。 <a class="header-anchor" href="#初九-需於郊-利用恆-無咎。-象曰-需於郊-不犯難行也。利用恆-無咎-未失常也。" aria-label="Permalink to “初九：需於郊，利用恆，無咎。 象曰：需於郊，不犯難行也。利用恆，無咎，未失常也。”">​</a></h3><h3 id="九二-需於沙-小有言-終吉。-象曰-需於沙-衍在中也。雖小有言-以吉終也。" tabindex="-1">九二：需於沙，小有言，終吉。 象曰：需於沙，衍在中也。雖小有言，以吉終也。 <a class="header-anchor" href="#九二-需於沙-小有言-終吉。-象曰-需於沙-衍在中也。雖小有言-以吉終也。" aria-label="Permalink to “九二：需於沙，小有言，終吉。 象曰：需於沙，衍在中也。雖小有言，以吉終也。”">​</a></h3><h3 id="九三-需於泥-致寇至。-象曰-需於泥-災在外也。自我致寇-敬慎不敗也。" tabindex="-1">九三：需於泥，致寇至。 象曰：需於泥，災在外也。自我致寇，敬慎不敗也。 <a class="header-anchor" href="#九三-需於泥-致寇至。-象曰-需於泥-災在外也。自我致寇-敬慎不敗也。" aria-label="Permalink to “九三：需於泥，致寇至。 象曰：需於泥，災在外也。自我致寇，敬慎不敗也。”">​</a></h3><p>寇雖邇，不犯，不至，故曰自我致之，能用需道，故曰敬慎不敗也。</p><h3 id="六四-需於血-出自穴。-象曰-需於血-順以聽也。" tabindex="-1">六四：需於血，出自穴。 象曰：需於血，順以聽也。 <a class="header-anchor" href="#六四-需於血-出自穴。-象曰-需於血-順以聽也。" aria-label="Permalink to “六四：需於血，出自穴。 象曰：需於血，順以聽也。”">​</a></h3><p>需於血者，入險而傷也。出於險者，不競乃善也。以需血者，非需之地也。子曰：&quot;繋辭焉以盡其言，變而通之以盡利，此之謂也。&quot;</p><h3 id="九五-需於酒食-貞吉。-象曰-酒食貞吉-以中正也。" tabindex="-1">九五：需於酒食，貞吉。 象曰：酒食貞吉，以中正也。 <a class="header-anchor" href="#九五-需於酒食-貞吉。-象曰-酒食貞吉-以中正也。" aria-label="Permalink to “九五：需於酒食，貞吉。 象曰：酒食貞吉，以中正也。”">​</a></h3><p>需九五需於酒食貞吉，酒食者，福祿之謂也。</p><h3 id="上六-入於穴-有不速之客三人來-敬之終吉。-象曰-不速之客來-敬之終吉。雖不當位-未大失也。" tabindex="-1">上六：入於穴，有不速之客三人來，敬之終吉。 象曰：不速之客來，敬之終吉。雖不當位，未大失也。 <a class="header-anchor" href="#上六-入於穴-有不速之客三人來-敬之終吉。-象曰-不速之客來-敬之終吉。雖不當位-未大失也。" aria-label="Permalink to “上六：入於穴，有不速之客三人來，敬之終吉。 象曰：不速之客來，敬之終吉。雖不當位，未大失也。”">​</a></h3>',14)])])}const b=e(n,[["render",l]]);export{p as __pageData,b as default};
